// Traces de chenilles : pour chaque couple (direction d'entrée, direction de sortie), deux chenilles
// suivent une courbe de Bézier qui relie le bord d'entrée au bord de sortie en passant par le centre.
function trackPixels(di,dout){
  const nrm=([x,y])=>{const l=Math.hypot(x,y);return [x/l,y/l];},I=nrm(DIRS[di]),O=nrm(DIRS[dout]),c=7.5;
  const P0=[c-I[0]*8.5,c-I[1]*8.5],P2=[c+O[0]*8.5,c+O[1]*8.5],P1=[c,c],set=new Set();let len=0,prev=null;
  for(let t=0;t<=1.0001;t+=.01){const u=1-t;
    const px=u*u*P0[0]+2*u*t*P1[0]+t*t*P2[0],py=u*u*P0[1]+2*u*t*P1[1]+t*t*P2[1];
    let tx=2*u*(P1[0]-P0[0])+2*t*(P2[0]-P1[0]),ty=2*u*(P1[1]-P0[1])+2*t*(P2[1]-P1[1]);const tl=Math.hypot(tx,ty)||1;tx/=tl;ty/=tl;
    if(prev)len+=Math.hypot(px-prev[0],py-prev[1]);prev=[px,py];
    if(len%4>=2.2)continue;
    for(const sgn of [-1,1]){const x=Math.round(px-ty*3.5*sgn),y=Math.round(py+tx*3.5*sgn);if(x>=0&&y>=0&&x<16&&y<16)set.add(x+','+y);}}
  return set;}
for(let i=0;i<8;i++)for(let o=0;o<8;o++){const px=trackPixels(i,o);
  for(let a=0;a<5;a++)PAT[`tk${i}${o}${a}`]=(x,y)=>px.has(x+','+y)&&((x*73+y*151+x*y*7)%97)%6>=a?'3':'.';}
